39	// assertTwiceState 断言主例数量保持不变：实物八件、有效占用六件、可再承诺
40	// 两件；c1 已用两件、未用三件且有效，c2 已用零件、未用三件且有效。查询时刻
41	// 必须早于两笔承诺的到期时刻（调用方需保证），以免查询本身确认到期。
42	func assertTwiceState(t *testing.T, s *Store, now time.Time) {
43		t.Helper()
44		st, err := s.PartStatus("part1", now)
45		if err != nil {
46			t.Fatalf("part status: %v", err)
47		}
48		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 6 || st.Committable != 2 {
49			t.Fatalf("stock = phys %d / occupied %d / committable %d, want 8/6/2",
50				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
51		}
52		d1, ok1 := detailByID(st, "c1")
53		d2, ok2 := detailByID(st, "c2")
54		if !ok1 || !ok2 {
55			t.Fatalf("commitment detail missing: c1=%v c2=%v", ok1, ok2)
56		}
57		if d1.Status != CommitmentActive || d1.UsedQuantity != 2 || d1.RemainingQuantity != 3 {
58			t.Fatalf("c1 detail = %+v, want active/used=2/remaining=3", d1)
59		}
60		if d2.Status != CommitmentActive || d2.UsedQuantity != 0 || d2.RemainingQuantity != 3 {
61			t.Fatalf("c2 detail = %+v, want active/used=0/remaining=3", d2)
62		}
63	}
