65	// TestUsageReuseBindsCommitAndQuantityNotTime 验证成功使用只与承诺编号、数量
66	// 绑定：仅本次提交时刻改变不构成冲突，原样取回首次结果；改数量或改承诺编号
67	// 任一项即冲突，且冲突后原记录与全部数量不变。
68	func TestUsageReuseBindsCommitAndQuantityNotTime(t *testing.T) {
69		s, first := usedTwiceStore(t)
70	
71		// 仅本次当前时刻不同：不是冲突，原样取回首次使用结果，不再次扣减。
72		later := nowOK.Add(5 * day)
73		got, err := s.Use("u1", "c1", 2, later)
74		if err != nil || got != first {
75			t.Fatalf("same content at later time = %+v, err %v; want first result %+v", got, err, first)
76		}
77		assertTwiceState(t, s, later)
78	
79		// 改数量：冲突。
80		if u, err := s.Use("u1", "c1", 1, later); !errors.Is(err, ErrConflict) || u != (Usage{}) {
81			t.Fatalf("changed quantity: usage=%+v err=%v, want ErrConflict with empty result", u, err)
82		}
83		// 改承诺编号：冲突。
84		if u, err := s.Use("u1", "c2", 2, later); !errors.Is(err, ErrConflict) || u != (Usage{}) {
85			t.Fatalf("changed commitment: usage=%+v err=%v, want ErrConflict with empty result", u, err)
86		}
87	
88		// 冲突不扣减、不释放，原成功使用记录不被新内容替换。
89		assertTwiceState(t, s, later)
90		if again, err := s.Use("u1", "c1", 2, later); err != nil || again != first {
91			t.Fatalf("original content after conflicts = %+v, err %v; want first result %+v", again, err, first)
92		}
93	}
