147	// TestUsageConflictPrecedenceOverClosedTarget 验证复用成功编号改指向另一笔
148	// 已取消或已确认到期的承诺时，仍按编号冲突处理，而不是 ErrCommitmentClosed；
149	// 冲突不改变取消/到期结果、不确认到期、不扣减或释放任何数量。
150	func TestUsageConflictPrecedenceOverClosedTarget(t *testing.T) {
151		t.Run("target canceled", func(t *testing.T) {
152			s, _ := usedTwiceStore(t)
153			if _, err := s.Cancel("c2", nowOK); err != nil {
154				t.Fatalf("cancel c2: %v", err)
155			}
156			// 复用 u1 改指向已取消的 c2：编号冲突优先。
157			if _, err := s.Use("u1", "c2", 2, nowOK.Add(day)); !errors.Is(err, ErrConflict) {
158				t.Fatalf("point to canceled commitment: got %v, want ErrConflict", err)
159			}
160			c2, _ := s.Commitment("c2")
161			c1, _ := s.Commitment("c1")
162			if !c2.Canceled || c2.Expired || c2.Used != 0 {
163				t.Fatalf("canceled c2 changed by conflict: %+v", c2)
164			}
165			if c1.Used != 2 || c1.Canceled || c1.Expired {
166				t.Fatalf("c1 changed by conflict: %+v", c1)
167			}
168			// 取消释放 c2 的三件占用：实物仍八件，有效占用仅 c1 的三件。
169			st, _ := s.PartStatus("part1", nowOK.Add(day))
170			if st.PhysicalRemaining != 8 || st.ActiveOccupied != 3 || st.Committable != 5 {
171				t.Fatalf("stock after conflict = %+v, want phys=8 occupied=3 committable=5", st)
172			}
173			if d, _ := detailByID(st, "c2"); d.Status != CommitmentCanceled {
174				t.Fatalf("c2 status = %q, want canceled", d.Status)
175			}
176		})
177	
178		t.Run("target confirmed expired", func(t *testing.T) {
179			s := newStore(t)
180			// c2 使用更早的到期时刻，先于 c1 到期并已被正常确认。
181			c2Expiry := nowOK.Add(2 * day)
182			if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
183				t.Fatalf("reserve c1: %v", err)
184			}
185			if _, err := s.Reserve("c2", "r1", "part1", 3, c2Expiry, nowOK); err != nil {
186				t.Fatalf("reserve c2: %v", err)
187			}
188			first, err := s.Use("u1", "c1", 2, nowOK)
189			if err != nil {
190				t.Fatalf("use u1: %v", err)
191			}
192			// 由库存查询正常确认 c2 到期，释放三件占用。
193			if _, err := s.PartStatus("part1", c2Expiry); err != nil {
194				t.Fatalf("confirm c2 expiry via query: %v", err)
195			}
196			// 复用 u1 改指向已到期的 c2（提交当前时刻也达到其到期时刻）：仍是冲突。
197			if u, err := s.Use("u1", "c2", 2, c2Expiry); !errors.Is(err, ErrConflict) || u != (Usage{}) {
198				t.Fatalf("point to expired commitment: usage=%+v err=%v, want ErrConflict", u, err)
199			}
200			c2, _ := s.Commitment("c2")
201			c1, _ := s.Commitment("c1")
202			if !c2.Expired || c2.Canceled || c2.Used != 0 {
203				t.Fatalf("expired c2 changed by conflict: %+v", c2)
204			}
205			if c1.Used != 2 || c1.Expired || c1.Canceled {
206				t.Fatalf("c1 changed by conflict: %+v", c1)
207			}
208			// 原内容仍取回首次结果，不再次扣减；c1 到期时刻更晚，冲突未波及它。
209			if got, err := s.Use("u1", "c1", 2, c2Expiry); err != nil || got != first {
210				t.Fatalf("retry original content: got %+v err %v, want %+v", got, err, first)
211			}
212			// 回到 c2 到期前时刻查看：c2 到期确认不可逆，c1 仍有效、占用三件。
213			st, _ := s.PartStatus("part1", c2Expiry.Add(-time.Second))
214			if st.PhysicalRemaining != 8 || st.ActiveOccupied != 3 || st.Committable != 5 {
215				t.Fatalf("stock = %+v, want phys=8 occupied=3 committable=5", st)
216			}
217			d1, _ := detailByID(st, "c1")
218			d2, _ := detailByID(st, "c2")
219			if d1.Status != CommitmentActive || d1.RemainingQuantity != 3 {
220				t.Fatalf("c1 = %+v, want active/remaining=3", d1)
221			}
222			if d2.Status != CommitmentExpired || d2.RemainingQuantity != 3 {
223				t.Fatalf("c2 = %+v, want expired/remaining=3", d2)
224			}
225		})
226	}
