package main

import (
	"errors"
	"fmt"
	"time"

	"github.com/descikazuyq/warranty-parts/warranty"
)

func main() {
	s := warranty.NewStore()
	// must 用于预期成功的操作：遇到意外错误立即停止，不继续输出成功结果。
	must := func(err error) {
		if err != nil {
			panic(err)
		}
	}
	// expectErr 用于预期拒绝：错误必须恰好是目标原因，否则立即停止，
	// 不把真正的意外错误当成“预期拒绝”略过。
	expectErr := func(err error, target error) {
		if !errors.Is(err, target) {
			panic(fmt.Sprintf("want %v, got %v", target, err))
		}
	}

	// 固定时刻：2026-01-01 购买、保修三百六十五天，全程在保；
	// 所有操作都取同一固定时刻，承诺全程未取消且未到期。
	purchase := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	now := purchase.AddDate(0, 0, 10) // 2026-01-11，保修期内
	expiry := purchase.AddDate(0, 0, 40)

	// 登记：产品始终在保、故障代码 NOISE 不在除外清单中；备件初始库存十件。
	must(s.RegisterProduct("P1", purchase, 365, []string{"BROKEN_SEAL"}))
	must(s.RegisterPart("PART-A", 10))
	must(s.SubmitRequest("REQ-1", "P1", "NOISE"))

	// 为已知请求预留五件（为这次已知请求预留）。
	_, err := s.Reserve("COMMIT-1", "REQ-1", "PART-A", 5, expiry, now)
	must(err)

	// 先用另一个使用编号成功领取两件：
	// 承诺已用两件、未用三件；实物剩余八件、有效占用三件、可承诺五件。
	u2, err := s.Use("USE-1", "COMMIT-1", 2, now)
	must(err)
	fmt.Printf("use-2     : id=%s commitment=%s qty=%d\n", u2.ID, u2.CommitmentID, u2.Quantity)

	show := func(label string) {
		c, err := s.Commitment("COMMIT-1")
		must(err)
		ps, err := s.PartStatus("PART-A", now)
		must(err)
		fmt.Printf("%-9s qty=%d used=%d unused=%d | physical=%d occupied=%d committable=%d\n",
			label, c.Quantity, c.Used, c.Unused(),
			ps.PhysicalRemaining, ps.ActiveOccupied, ps.Committable)
		us, err := s.CommitmentUsages("COMMIT-1")
		must(err)
		var parts string
		total := 0
		for _, u := range us {
			parts += fmt.Sprintf(" {%s %s %d}", u.ID, u.CommitmentID, u.Quantity)
			total += u.Quantity
		}
		fmt.Printf("%-9s usages(len=%d,sum=%d):%s\n", label, len(us), total, parts)
	}

	show("setup:")

	// 用一个从未成功过的使用编号领取四件：本笔承诺未用仅三件，
	// 即使仓库实物足够（八件）也应得到 ErrUsageExceeded，整次不扣减——
	// 不能先领走允许的三件。
	_, err = s.Use("USE-2", "COMMIT-1", 4, now)
	exceeded := errors.Is(err, warranty.ErrUsageExceeded)
	expectErr(err, warranty.ErrUsageExceeded)
	fmt.Println("reject-4  : ErrUsageExceeded =", exceeded)

	// 拒绝后：承诺数量和三项库存账目保持原值；该承诺的成功使用明细
	// 仍只有此前两件的记录（USE-2 从未成功过，不进明细）。
	show("after-4:")

	// 沿用刚才失败的编号，仍指向原承诺，把数量改成三件：应成功，
	// 返回这次使用的编号、承诺编号和数量。
	u3, err := s.Use("USE-2", "COMMIT-1", 3, now)
	must(err)
	fmt.Printf("use-3     : id=%s commitment=%s qty=%d\n", u3.ID, u3.CommitmentID, u3.Quantity)

	// 此时承诺累计已用五件、未用零件；账目变为实物五件、有效占用零件、
	// 可承诺五件；成功使用明细只包含两件和三件这两次领取，合计五件。
	show("after-3:")

	// 再次按相同编号、承诺和三件数量提交：取回同一成功结果，
	// 不再扣减，也不增加明细。
	u3b, err := s.Use("USE-2", "COMMIT-1", 3, now)
	must(err)
	fmt.Printf("retry-3   : id=%s commitment=%s qty=%d same=%v\n",
		u3b.ID, u3b.CommitmentID, u3b.Quantity, u3b == u3)
	show("retry3:")

	// 再把数量改回最初被拒绝的四件：编号内容已由三件的首次成功确定，
	// 此时应返回 ErrConflict；三件的成功结果和账目都保留。
	_, err = s.Use("USE-2", "COMMIT-1", 4, now)
	conflict := errors.Is(err, warranty.ErrConflict)
	expectErr(err, warranty.ErrConflict)
	fmt.Println("back-to-4 : ErrConflict =", conflict)
	show("final:")
}
